            board.InitTurn();

            List<string> actions = ["MSG Eat your vegetables! And your iron!", .. GetActions(board, turn).Select(a => a.ToString())];
            Console.WriteLine(string.Join(";", actions));

#if DEBUG
            if (Debugger.IsAttached) break;
#endif
        }
