using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System;


public class Board
{
    public int ID;
    public static int Width;
    public static int Height;
    public static Cell[,] Grid;
    public static List<Cell> Irons = [];
    public static Cell[] Shacks = new Cell[2];
    private static List<Cell> walkableCells = [];
    public static bool IsEarlyGame;

    public int[] TreeZobrist;
    public Board Parent;
    public int Depth;
    public List<Action> Actions = [];
    public Inventory[] Inventories = new Inventory[2];
    public List<Troll> Trolls = [];
    public List<Tree> Trees = [];
    public double Score;

    public static int idCounter;
    public Board()
    {
        ID = idCounter++;
    }

    public static void InitNeighbors()
    {
        foreach (Cell cell in Grid) cell.InitNeighbors(Grid);
        foreach (Cell cell in Grid) cell.InitDist();
        foreach (Cell cell in Grid)
        {
            if (cell.IsIron) Irons.Add(cell);
            if (cell.Character == '0') Shacks[0] = cell;
            if (cell.Character == '1') Shacks[1] = cell;
            if (cell.IsWalkable) walkableCells.Add(cell);
        }
    }

    public Board Expand(Plan rootPlan, List<Action> actions)
    {
        Board next = new()
        {
            Parent = this,
            Depth = this.Depth + 1,
            Actions = actions,
            Inventories = [.. this.Inventories.Select(inv => new Inventory(inv))],
            Trolls = [.. this.Trolls.Select(t => new Troll(t))],
            Trees = [.. this.Trees.Select(t => new Tree(t))],
            TreeZobrist = [.. this.TreeZobrist],
        };

        foreach (Action a in actions) a.ApplyOn(next);
        foreach (Tree t in next.Trees) t.Tick();
        next.UpdateScore(rootPlan);
        return next;
    }

    private static int[] itemScore = [1, 1, 1, 1, 0, 4];
    private static int[] itemCurrentScore;
    public void InitTurn()
    {
        idCounter = 1;
        TreeZobrist = new int[4];
        foreach (Tree t in Trees) TreeZobrist[t.Type] ^= t.Cell.Zobrist;

        itemCurrentScore = [.. itemScore];
        int[] trainCost = GetNextPlannedTrain();
        IsEarlyGame = trainCost != null;
        if (!IsEarlyGame)
        {
            if (Inventories[0].Items[Inventory.BANANA] < 5 && Trees.Count(t => t.Type == Inventory.BANANA && t.Cell.Dist[Shacks[0].ID] < 4) < 3) itemCurrentScore[Inventory.BANANA] = 20;
            return;
        }
        trainCost = [.. trainCost.Select(c => Trolls.Count(t => t.IsMine) + c * c)];
        for (int i = 0; i <= 2; i++)
        {
            if (trainCost[i] > Inventories[0].Items[i]) itemCurrentScore[i] += 5;
        }
        if (trainCost[3] > Inventories[0].Items[Inventory.IRON]) itemCurrentScore[Inventory.IRON] += 5;
    }

    private void UpdateScore(Plan rootPlan)
    {
        Score = 1.1 * Parent.Score;
        List<Troll> myTrolls = [.. Trolls.Where(t => t.IsMine)];
        Score += 200 * myTrolls.Sum(t => 10 + 1.5 * t.MovementSpeed + t.HarvestPower + t.ChopPower + 2 * t.CarryCapacity);
        for (int i = 0; i < 6; i++)
        {
            foreach (Troll t in myTrolls) Score += 0.5 * t.Inventory.Items[i] * itemCurrentScore[i];
            Score += Inventories[0].Items[i] * itemCurrentScore[i];
        }

        List<Troll> finished = [.. myTrolls.Where(t => t.IsMine && rootPlan.MacroActions.ContainsKey(t.ID) && !Actions.Any(a => a.Troll?.ID == t.ID))];
        Score += finished.Sum(f => 2 * f.CarryCapacity + f.MovementSpeed) * itemCurrentScore.Max() / 100.0;

        if (IsEarlyGame)
        {
            for (int type = 0; type < Inventory.BANANA; type++) Score += GetTreeScore(type) * itemCurrentScore[type];
        }
        else Score += GetPalmScore();
    }

    private static Dictionary<int, double> treeScoreLookup = [];
    private double GetTreeScore(int type)
    {
        int hash = TreeZobrist[type];
        if (treeScoreLookup.TryGetValue(hash, out double result)) return result;
        List<double> scores = [];
        foreach (Tree t in Trees.Where(t => t.Type == type)) scores.Add(1.0 / ((Shacks[0].Dist[t.Cell.ID] - 0.11 * Shacks[1].Dist[t.Cell.ID]) * Math.Pow(t.CooldownInterval, 1.5)));
        scores = [.. scores.OrderByDescending(s => s)];
        for (int i = 0; i < scores.Count; i++) result += (i == 0 ? 5000 : 10.0 / i) * scores[i];
        treeScoreLookup[hash] = result;
        return result;
    }

    private double GetPalmScore()
    {
        int hash = TreeZobrist[Inventory.BANANA];
        if (treeScoreLookup.TryGetValue(hash, out double result)) return result;
        foreach (Tree t in Trees.Where(t => t.Type == Inventory.BANANA)) result += 1000.0 / ((Shacks[0].Dist[t.Cell.ID] - 0.11 * Shacks[1].Dist[t.Cell.ID]) * t.CooldownInterval);
        treeScoreLookup[hash] = result;
        return result;
    }

    public (Board, Plan) PlayAllPlan(Plan plan)
    {
        Board result = this;
        Plan workingSet = new(plan);
        Plan remainderPlan = null;
        for (int t = 0; t < Program.SIM_DEPTH; t++)
        {
            List<Action> actions = [.. workingSet.GetNextActions(result)];
            result = result.Expand(plan, actions);
            foreach (Action action in actions.Where(a => a.Completed && workingSet.MacroActions.ContainsKey(a.Key)))
            {
                workingSet.MacroActions[action.Key].RemoveAt(0);
                if (workingSet.MacroActions[action.Key].Count == 0) workingSet.MacroActions.Remove(action.Key);
            }
            if (t == 0) remainderPlan = new Plan(workingSet);
        }
        return (result, remainderPlan);
    }

    public int[] GetNextPlannedTrain()
    {
        int trollsCount = Trolls.Count(t => t.IsMine);
        if (trollsCount == 5) return null;
        int[] attributes = [1, 2, 1, 1]; // move, carry, harvest, chop
        if (trollsCount > 2) attributes[1]++;
        if (trollsCount > 2) attributes[3]++;
        if (trollsCount > 3) attributes[0]++;
        int[] inv = Inventories[0].Items;
        if (inv[Inventory.PLUM] + 2 >= trollsCount + (attributes[0] + 1) * (attributes[0] + 1)) attributes[0]++;
        if (inv[Inventory.LEMON] + attributes[Inventory.LEMON] >= trollsCount + (attributes[1] + 1) * (attributes[1] + 1)) attributes[1]++;
        if (inv[Inventory.IRON] >= trollsCount + (attributes[3] + 1) * (attributes[3] + 1)) attributes[3]++;
        return attributes;
    }

    public List<Cell> GetEmptyCells()
    {
        HashSet<Cell> planted = [.. Trees.Select(t => t.Cell)];
        return [.. walkableCells.Where(c => !planted.Contains(c))];
    }
}

public enum ActionType
{
    MOVE,
    HARVEST,
    DROP,
    PICK,
    MINE,
    CHOP,
    TRAIN,
    PLANT
}


public class Action
{
    public Troll Troll;
    public ActionType ActionType;
    public Cell Target;
    public int PlantType;
    public int[] TrainAttributes;
    public bool Completed;
    public int Key => Troll?.ID ?? -1;

    public override string ToString()
    {
        switch (ActionType)
        {
            case ActionType.MOVE: return $"MOVE {Troll.ID} {Target.X} {Target.Y}";
            case ActionType.HARVEST: return $"HARVEST {Troll.ID}";
            case ActionType.DROP: return $"DROP {Troll.ID}";
            case ActionType.PICK: return $"PICK {Troll.ID} {PlantType}";
            case ActionType.MINE: return $"MINE {Troll.ID}";
            case ActionType.CHOP: return $"CHOP {Troll.ID}";
            case ActionType.TRAIN: return $"TRAIN {string.Join(" ", TrainAttributes)}";
            case ActionType.PLANT: return $"PLANT {Troll.ID} {PlantType}";
            default: return "WAIT";
        }
    }

    private static string[] itemNames = ["PLUM", "LEMON", "APPLE", "BANANA", "IRON", "WOOD"];
    public string PrintVerbose()
    {
        switch (ActionType)
        {
            case ActionType.MOVE: return $"MOVE {Troll.ID} {Target.X} {Target.Y}";
            case ActionType.HARVEST: return $"HARVEST {Troll.ID} {Target} {itemNames[PlantType]}";
            case ActionType.DROP: return $"DROP {Troll.ID}";
            case ActionType.PICK: return $"PICK {Troll.ID} {itemNames[PlantType]}";
            case ActionType.MINE: return $"MINE {Troll.ID} {Target}";
            case ActionType.CHOP: return $"CHOP {Troll.ID} {Target}";
            case ActionType.TRAIN: return $"TRAIN {string.Join(" ", TrainAttributes)}";
            case ActionType.PLANT: return $"PLANT {Troll.ID} {itemNames[PlantType]} {Target}";
            default: return "WAIT";
        }
    }

    public void ApplyOn(Board board)
    {
        Troll troll = board.Trolls.FirstOrDefault(t => t.ID == Troll?.ID);
        switch (ActionType)
        {
            case ActionType.MOVE:
                troll.Cell = Target;
                break;
            case ActionType.HARVEST:
                Tree tree = board.Trees.FirstOrDefault(t => t.Cell == Target);
                if (tree != null)
                {
                    int harvest = Math.Min(troll.FreeCarryCapacity, Math.Min(tree.Fruits, troll.HarvestPower));
                    troll.Inventory.Items[tree.Type] += harvest;
                    tree.Fruits -= harvest;
                    Completed = tree.Fruits == 0 || troll.FreeCarryCapacity == 0;
                }
                break;
            case ActionType.DROP:
                Inventory invDrop = board.Inventories[troll.IsMine ? 0 : 1];
                for (int i = 0; i < invDrop.Items.Length; i++)
                {
                    invDrop.Items[i] += troll.Inventory.Items[i];
                    troll.Inventory.Items[i] = 0;
                }
                Completed = true;
                break;
            case ActionType.PICK:
                Inventory invPick = board.Inventories[troll.IsMine ? 0 : 1];
                if (invPick.Items[PlantType] > 0 && troll.FreeCarryCapacity > 0)
                {
                    invPick.Items[PlantType]--;
                    troll.Inventory.Items[PlantType]++;
                    Completed = true;
                }
                break;
            case ActionType.MINE:
                troll.Inventory.Items[Inventory.IRON] += Math.Min(troll.FreeCarryCapacity, troll.ChopPower);
                Completed = troll.FreeCarryCapacity == 0;
                break;
            case ActionType.CHOP:
                Tree chopTree = board.Trees.FirstOrDefault(t => t.Cell == Target);
                if (chopTree != null)
                {
                    chopTree.Health -= troll.ChopPower;
                    int harvest = Math.Min(troll.FreeCarryCapacity, chopTree.Size);
                    troll.Inventory.Items[Inventory.WOOD] += harvest;
                    if (chopTree.Health <= 0) board.Trees.Remove(chopTree);
                    Completed = chopTree.Health <= 0;
                }
                break;
            case ActionType.TRAIN:
                bool isMine = Board.Shacks[0] == Target;
                int baseCost = board.Trolls.Count(t => t.IsMine == isMine);
                int[] costs = [.. TrainAttributes.Select(t => baseCost + t * t)];
                Inventory invCost = new Inventory().Fill([costs[0], costs[1], costs[2], 0, costs[3], 0]);
                Inventory playerInv = board.Inventories[isMine ? 0 : 1];
                if (Enumerable.Range(0, invCost.Items.Length).All(i => playerInv.Items[i] >= invCost.Items[i]))
                {
                    for (int i = 0; i < playerInv.Items.Length; i++) playerInv.Items[i] -= invCost.Items[i];
                    Troll t = new Troll
                    {
                        ID = board.Trolls.Count,
                        Cell = isMine ? Board.Shacks[0] : Board.Shacks[1],
                        MovementSpeed = TrainAttributes[0],
                        CarryCapacity = TrainAttributes[1],
                        HarvestPower = TrainAttributes[2],
                        ChopPower = TrainAttributes[3],
                        IsMine = isMine,
                        Inventory = new() { Items = new int[6] }
                    };
                    board.Trolls.Add(t);
                    Completed = true;
                }
                break;
            case ActionType.PLANT:
                Tree blocking = board.Trees.FirstOrDefault(t => t.Cell == Target);
                if (blocking == null)
                {
                    troll.Inventory.Items[PlantType]--;
                    board.Trees.Add(new Tree { Cell = Target, Type = PlantType });
                    board.TreeZobrist[PlantType] ^= Target.Zobrist;
                    Completed = true;
                }
                break;
            default:
                Completed = true;
                break;
        }
    }
}

public static class Extensions
{
    public static T GetItem<T>(this Random random, List<T> list)
    {
        if (list.Count == 0) return default;
        return list[random.Next(list.Count)];
    }

    public static T GetBiasedRandom<T>(this Random random, List<T> list, Func<T, double> score)
    {
        if (list.Count == 0) return default;
        double[] scores = [.. list.Select(score)];
        double rnd = random.NextDouble() * scores.Sum();
        int idx = 0;
        while (rnd >= scores[idx]) rnd -= scores[idx++];
        return list[idx];
    }
}


public class Cell
{
    public char Character;
    public int X;
    public int Y;
    public int ID => X + Board.Width * Y;
    public bool IsWalkable;
    public bool IsWater;
    public bool IsIron;
    public bool IsNearWater;
    public bool IsNearIron;
    public int[] CooldownInterval;
    public List<Cell> Neighbors = [];
    public int[] Dist;
    public int Zobrist;

    private static Random random = new(0);
    public Cell(int x, int y, char c)
    {
        this.X = x;
        this.Y = y;
        this.Character = c;
        IsWalkable = c == '.';
        IsWater = c == '~';
        IsIron = c == '+';
        Zobrist = random.Next();
    }

    private int[] dx = [0, 1, 0, -1];
    private int[] dy = [1, 0, -1, 0];
    private static int[] PLANT_COOLDOWN = { 8, 8, 9, 6 };
    private static int[] PLANT_WATER_COOLDOWN_BOOST = { 5, 5, 7, 2 };
    public void InitNeighbors(Cell[,] grid)
    {
        for (int dir = 0; dir < 4; dir++)
        {
            int x = this.X + dx[dir];
            int y = this.Y + dy[dir];
            if (x >= 0 && x < Board.Width && y >= 0 && y < Board.Height) Neighbors.Add(grid[x, y]);
        }
        IsNearWater = Neighbors.Any(n => n.IsWater);
        IsNearIron = Neighbors.Any(n => n.IsIron);
        CooldownInterval = IsNearWater ? [.. Enumerable.Range(0, PLANT_COOLDOWN.Length).Select(i => PLANT_COOLDOWN[i] - PLANT_WATER_COOLDOWN_BOOST[i])] : PLANT_COOLDOWN;
    }

    public void InitDist()
    {
        Dist = new int[Board.Width * Board.Height];
        Array.Fill(Dist, 1000);
        Queue<Cell> queue = [];
        queue.Enqueue(this);
        Dist[ID] = 0;
        while (queue.Count > 0)
        {
            Cell q = queue.Dequeue();
            foreach (Cell n in q.Neighbors)
            {
                if (Dist[n.ID] < 1000) continue;
                Dist[n.ID] = Dist[q.ID] + 1;
                if (n.IsWalkable) queue.Enqueue(n);
            }
        }
    }

    public override string ToString() => $"({X}/{Y})";
}


public class Plan
{
    public Dictionary<int, List<Action>> MacroActions = [];
    public Plan() { }
    public Plan(Plan plan)
    {
        this.MacroActions = plan.MacroActions.ToDictionary(p => p.Key, p => p.Value.ToList());
    }

    public IEnumerable<Action> GetNextActions(Board board)
    {
        List<Action> moves = [];
        List<Troll> unused = [.. board.Trolls.Where(t => t.IsMine)];
        List<Cell> blockedCells = [];
        foreach (int id in MacroActions.Keys)
        {
            Action macro = MacroActions[id][0];
            Troll troll = board.Trolls.FirstOrDefault(t => t.ID == id);
            if (troll != null)
            {
                unused.Remove(troll);
                blockedCells.Add(troll.Cell);
            }
            if (macro.ActionType == ActionType.HARVEST)
            {
                if (troll.Cell == macro.Target) yield return new Action { Troll = troll, Target = macro.Target, PlantType = macro.PlantType, ActionType = macro.ActionType };
                else moves.Add(new Action { Troll = troll, Target = macro.Target, ActionType = ActionType.MOVE });
            }
            if (macro.ActionType == ActionType.DROP)
            {
                if (troll.Cell.Neighbors.Contains(macro.Target)) yield return new Action { Troll = troll, Target = macro.Target, ActionType = macro.ActionType };
                else moves.Add(new Action { Troll = troll, Target = macro.Target, ActionType = ActionType.MOVE });
            }
            if (macro.ActionType == ActionType.PICK)
            {
                if (troll.Cell.Neighbors.Contains(macro.Target)) yield return new Action { Troll = troll, Target = macro.Target, PlantType = macro.PlantType, ActionType = macro.ActionType };
                else moves.Add(new Action { Troll = troll, Target = macro.Target, ActionType = ActionType.MOVE });
            }
            if (macro.ActionType == ActionType.MINE)
            {
                if (troll.Cell.IsNearIron) yield return new Action { Troll = troll, Target = macro.Target, ActionType = macro.ActionType };
                else moves.Add(new Action { Troll = troll, Target = macro.Target, ActionType = ActionType.MOVE });
            }
            if (macro.ActionType == ActionType.CHOP)
            {
                if (troll.Cell == macro.Target) yield return new Action { Troll = troll, Target = macro.Target, ActionType = macro.ActionType };
                else moves.Add(new Action { Troll = troll, Target = macro.Target, ActionType = ActionType.MOVE });
            }
            if (macro.ActionType == ActionType.TRAIN)
            {
                yield return new Action { TrainAttributes = macro.TrainAttributes, Target = macro.Target, ActionType = macro.ActionType };
            }
            if (macro.ActionType == ActionType.PLANT)
            {
                if (troll.Cell == macro.Target) yield return new Action { Troll = troll, Target = macro.Target, PlantType = macro.PlantType, ActionType = macro.ActionType };
                else moves.Add(new Action { Troll = troll, Target = macro.Target, ActionType = ActionType.MOVE });
            }
        }

        // make unused trolls drop items, then vanish into thin air
        foreach (Troll troll in unused)
        {
            if (troll.Inventory.Total > 0)
            {
                if (troll.Cell.Neighbors.Contains(Board.Shacks[0])) yield return new Action { Troll = troll, Target = Board.Shacks[0], ActionType = ActionType.DROP };
                else moves.Add(new Action { Troll = troll, Target = Board.Shacks[0], ActionType = ActionType.MOVE });
            }
            else if (board.Depth <= 5) blockedCells.Add(troll.Cell);
        }

        foreach (Action move in ResolveMoves(blockedCells, moves)) yield return move;
    }

    private IEnumerable<Action> ResolveMoves(List<Cell> blockedCells, List<Action> moves)
    {
        List<(Action move, List<List<Cell>> nextSteps)> actions = [];
        foreach (Action move in moves) actions.Add((move, move.Troll.GetNextCandidates(move.Target)));

        while (true)
        {
            // easy moves without blocking
            bool success = true;
            while (success)
            {
                success = false;
                foreach (var action in actions.ToArray())
                {
                    List<Cell> candidates = action.nextSteps[^1];
                    Cell next = candidates.OrderBy(c => Program.Random.Next()).FirstOrDefault(c => !blockedCells.Contains(c));
                    if (next == null) continue;
                    blockedCells.Remove(action.move.Troll.Cell);
                    blockedCells.Add(next);
                    action.move.Target = next;
                    actions.Remove(action);
                    success = true;
                    yield return action.move;
                }
            }

            // swap positions
            // TODO support more than 2 trolls?
            success = true;
            while (success)
            {
                success = false;
                foreach (var action1 in actions)
                {
                    foreach (var action2 in actions)
                    {
                        if (action1.nextSteps[^1].Contains(action2.move.Troll.Cell) &&
                        action2.nextSteps[^1].Contains(action1.move.Troll.Cell))
                        {
                            action1.move.Target = action2.move.Troll.Cell;
                            action2.move.Target = action1.move.Troll.Cell;
                            actions.Remove(action1);
                            actions.Remove(action2);
                            yield return action1.move;
                            yield return action2.move;
                            success = true;
                            goto didSwap;
                        }
                    }
                }
            didSwap:;
            }

            if (actions.Count == 0) break;

            // merge nextSteps, going a bit shorter
            int max = actions.Max(a => a.nextSteps.Count);
            if (max == 2) break;
            foreach (var action in actions.Where(a => a.nextSteps.Count == max))
            {
                action.nextSteps[^2].AddRange(action.nextSteps[^1]);
                action.nextSteps.RemoveAt(action.nextSteps.Count - 1);
            }
        }
    }
}


public class Troll
{
    public int ID;
    public bool IsMine;
    public Cell Cell;
    public Inventory Inventory;
    public int MovementSpeed;
    public int CarryCapacity;
    public int HarvestPower;
    public int ChopPower;
    public int FreeCarryCapacity => CarryCapacity - Inventory.Total;

    public Troll() { }
    public Troll(Troll t)
    {
        this.ID = t.ID;
        this.IsMine = t.IsMine;
        this.Cell = t.Cell;
        this.Inventory = new Inventory(t.Inventory);
        this.MovementSpeed = t.MovementSpeed;
        this.CarryCapacity = t.CarryCapacity;
        this.HarvestPower = t.HarvestPower;
        this.ChopPower = t.ChopPower;
    }

    private static Dictionary<int, List<Cell>> rangeLookup = [];
    public List<Cell> GetCellsInRange()
    {
        int key = Cell.ID + Board.Width * Board.Height * MovementSpeed;
        if (rangeLookup.TryGetValue(key, out List<Cell> result)) return result;
        result = [];
        for (int x = Math.Max(0, Cell.X - MovementSpeed); x <= Math.Min(Board.Width - 1, Cell.X + MovementSpeed); x++)
        {
            for (int y = Math.Max(0, Cell.Y - MovementSpeed); y <= Math.Min(Board.Height - 1, Cell.Y + MovementSpeed); y++)
            {
                if (Board.Grid[x, y].IsWalkable && Cell.Dist[x + Board.Width * y] <= MovementSpeed) result.Add(Board.Grid[x, y]);
            }
        }
        rangeLookup[key] = result;
        return result;
    }

    public List<List<Cell>> GetNextCandidates(Cell target)
    {
        int baseDist = target.Dist[Cell.ID];
        List<List<Cell>> result = [.. Enumerable.Range(0, MovementSpeed + 1).Select(i => new List<Cell>())];
        foreach (Cell next in GetCellsInRange())
        {
            int d = baseDist - target.Dist[next.ID];
            if (d < 0) continue;
            result[d].Add(next);
        }
        return result;
    }

    public int GetDist(Cell c) => this.Cell.Dist[c.ID];
    public double GetDistPow(Cell c, double pow) => Math.Max(0.5, Math.Pow(GetDist(c), pow));

    public override string ToString() => $"[{ID}] {Cell}";
}


public class Inventory
{
    public const int PLUM = 0;
    public const int LEMON = 1;
    public const int APPLE = 2;
    public const int BANANA = 3;
    public const int IRON = 4;
    public const int WOOD = 5;

    public int[] Items;
    public Inventory() { }
    public Inventory(Inventory inv) { Items = [.. inv.Items]; }
    public int Total => Items.Sum();

    public Inventory Fill(IEnumerable<int> values)
    {
        Items = [.. values];
        return this;
    }
}

public class Tree
{
    public Cell Cell;
    public int Type;
    public int Size;
    public int Fruits;
    public int Health;
    public int CurrentCooldown;
    public int CooldownInterval => Cell.CooldownInterval[Type];

    private static int[] PLANT_FINAL_HEALTH = { 12, 12, 20, 6 };
    private static int[] PLANT_DELTA_HEALTH = { 2, 2, 3, 1 };

    public Tree() { }
    public Tree(Tree t)
    {
        this.Cell = t.Cell;
        this.Type = t.Type;
        this.Size = t.Size;
        this.Fruits = t.Fruits;
        this.Health = t.Health;
        this.CurrentCooldown = t.CurrentCooldown;
    }

    public void Tick()
    {
        if (CurrentCooldown > 0) CurrentCooldown--;
        if (CurrentCooldown == 0 && Health > 0)
        {
            if (Size < 4)
            {
                if (Size == 0) Health = PLANT_FINAL_HEALTH[Type] - 3 * PLANT_DELTA_HEALTH[Type];
                else Health += PLANT_DELTA_HEALTH[Type];
                Size++;
                CurrentCooldown = CooldownInterval;
            }
            else if (Fruits < 3)
            {
                Fruits++;
                CurrentCooldown = CooldownInterval;
            }
        }
    }

    private static string[] treeNames = ["PLUM", "LEMON", "APPLE", "BANANA"];
    public override string ToString() => $"{Cell} {treeNames[Type]}";
}


