            List<string> actions = ["MSG Eat your vegetables! And your iron!", .. GetActions(board, turn).Select(a => a.ToString())];
            Console.WriteLine(string.Join(";", actions));

#if DEBUG
            if (Debugger.IsAttached) break;
#endif
        }
    }

    public static Random Random = new(0);
    private static Plan lastTurnPlan = null;
    private static List<Action> GetActions(Board board, int turn)
    {
        Stopwatch sw = Stopwatch.StartNew();
        Plan plan = lastTurnPlan == null ? new() : new(lastTurnPlan);
        foreach (var pair in plan.MacroActions.ToArray())
        {
            if (pair.Key == -1) continue;
            bool valid = true;
            Tree tree = board.Trees.FirstOrDefault(t => t.Cell == pair.Value[0].Target);
            Troll troll = board.Trolls.FirstOrDefault(t => t.ID == pair.Value[0].Troll.ID);
            if (pair.Value[0].ActionType == ActionType.HARVEST) valid = troll.FreeCarryCapacity > 0 && tree != null;
            if (pair.Value[0].ActionType == ActionType.CHOP) valid = troll.FreeCarryCapacity > 0 && tree != null;
            if (pair.Value[0].ActionType == ActionType.PLANT) valid = tree == null;
            if (pair.Value[0].ActionType == ActionType.DROP) valid = troll.Inventory.Total > 0;
            if (pair.Value[0].ActionType == ActionType.MINE) valid = troll.FreeCarryCapacity > 0;
            if (pair.Value[0].ActionType == ActionType.PICK) valid = troll.FreeCarryCapacity > 0 && board.Inventories[0].Items[pair.Value[0].PlantType] > 0;
            if (!valid) plan.MacroActions.Remove(pair.Key);
        }
        int[] nextTrain = board.GetNextPlannedTrain();
        if (nextTrain != null) plan.MacroActions[-1] = [new Action { ActionType = ActionType.TRAIN, TrainAttributes = nextTrain, Target = Board.Shacks[0] }];
        (Board best, lastTurnPlan) = board.PlayAllPlan(plan);
        List<Troll> myTrolls = [.. board.Trolls.Where(t => t.IsMine)];
        for (int i = 0; i < 50; i++)
        {
            Troll troll = Random.GetItem(myTrolls);
            Plan p = new(plan);
            List<Action> actions = GenerateRandomActions(board, troll, turn);
            if (actions.Count > 0) p.MacroActions[troll.ID] = actions;
            (Board b, Plan remainderPlan) = board.PlayAllPlan(p);
            if (b.Score >= best.Score)
            {
                plan = p;
                best = b;
                lastTurnPlan = remainderPlan;
            }
        }

        //Console.Error.WriteLine("plan score: " + best.Score + " @" + sw.ElapsedMilliseconds + " ms");
        //foreach (var actions in plan.MacroActions.OrderBy(a => a.Key))
        //    Console.Error.WriteLine($"[{actions.Key}] {string.Join(" - ", actions.Value.Select(a => a.PrintVerbose()))}");
        while (best.Parent.Parent != null) best = best.Parent;
        best.Actions = [.. best.Actions.Where(a => a.ActionType != ActionType.TRAIN || a.Completed)];
        return best.Actions;
    }

    private const int MACRO_ACTION_DEPTH = 2;
    public const int SIM_DEPTH = 15;
    private static bool CanDrop(int[] inv) => inv.Sum() > 0;
    private static bool CanTake(int[] inv, int capacity) => inv.Sum() < capacity;
    private static List<Action> GenerateRandomActions(Board board, Troll troll, int turn)
    {
        int[] inv = [.. troll.Inventory.Items];
        List<Action> result = [];
        for (int iter = 0; iter < 100 && result.Count < MACRO_ACTION_DEPTH; iter++)
        {
            int treeType = Random.Next(4);
            int action = Random.Next(5);
            if (action == 0 && Random.Next(5) == 0) action = 5; // MINE has same chance of HARVEST for a specific fruit
            if (result.Count > 0 && result[^1].ActionType == ActionType.PICK) action = 4; // pick -> plant
            switch (action)
            {
                case 0: // HARVEST
                    if (!CanTake(inv, troll.CarryCapacity)) break;
                    List<Tree> candidates = [.. board.Trees.Where(t => t.Size == 4 && t.Type == treeType)];
                    if (candidates.Count == 0) break;
                    Tree tree = Random.GetBiasedRandom(candidates, t => 1.0 / troll.GetDistPow(t.Cell, 1.5));
                    if (tree == null) break;
                    result.Add(new Action { Troll = troll, ActionType = ActionType.HARVEST, PlantType = tree.Type, Target = tree.Cell });
                    inv[tree.Type] += Math.Min(tree.Fruits, troll.CarryCapacity - inv.Sum());
                    break;
                case 1: // DROP
                    if (!CanDrop(inv)) break;
                    result.Add(new Action { Troll = troll, ActionType = ActionType.DROP, Target = Board.Shacks[0] });
                    Array.Fill(inv, 0);
                    break;
                case 2: // PICK
                    if (!CanTake(inv, troll.CarryCapacity)) break;
                    if (board.Inventories[0].Items[treeType] == 0) break;
                    //if (troll.ID == 0 && treeType == Inventory.LEMON) Debugger.Break();
                    result.Add(new Action { Troll = troll, ActionType = ActionType.PICK, PlantType = treeType, Target = Board.Shacks[0] });
                    inv[treeType]++;
                    break;
                case 3: // CHOP
                    if (Board.IsEarlyGame || !CanTake(inv, troll.CarryCapacity)) break;
                    Tree chopTree = Random.GetBiasedRandom(board.Trees, t => t.Size / troll.GetDistPow(t.Cell, 1.5));
                    if (chopTree == null) break;
                    result.Add(new Action { Troll = troll, ActionType = ActionType.CHOP, Target = chopTree.Cell });
                    inv[Inventory.WOOD] += Math.Min(troll.CarryCapacity - inv.Sum(), chopTree.Size);
                    break;
                case 4: // PLANT
                    List<int> seeds = [.. Enumerable.Range(0, 4).Where(i => inv[i] > 0)];
                    if (seeds.Count == 0) break;
                    treeType = Random.GetItem(seeds);
                    Cell cell = Random.GetBiasedRandom(board.GetEmptyCells(), c => 1.0 / (troll.GetDistPow(c, 1.5) * c.CooldownInterval[treeType]));
                    if (cell == null) break;
                    //if (treeType == Inventory.LEMON && cell.X == 8 && cell.Y == 4) Debugger.Break();
                    result.Add(new Action { Troll = troll, ActionType = ActionType.PLANT, PlantType = treeType, Target = cell });
                    inv[treeType]--;
                    break;
                case 5: // MINE
                    if (!Board.IsEarlyGame || !CanTake(inv, troll.CarryCapacity)) break;
                    result.Add(new Action { Troll = troll, ActionType = ActionType.MINE, Target = Random.GetBiasedRandom(Board.Irons, c => 1.0 / troll.GetDistPow(c, 1.5)) });
                    inv[Inventory.IRON] += troll.CarryCapacity - inv.Sum();
                    break;
            }
        }
        return result;
    }
}
